require_once __DIR__ . '/../includes/auth.php';$u=require_role(['superadmin']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']);$username=trim($_POST['username']);$password=$_POST['password'];$role=$_POST['role'];if(strlen($password)<8)$error='Use a password with at least 8 characters.';elseif(!in_array($role,['user','admin','superadmin'],true))$error='Invalid role.';else{try{$hash=password_hash($password,PASSWORD_DEFAULT);$s=$pdo->prepare("INSERT INTO accounts(full_name,username,password_hash,course_program,student_id,role,account_status) VALUES(?,?,?,?,?,?,?)");$s->execute([$name,$username,$hash,trim($_POST['course_program']),trim($_POST['student_id']),$role,$_POST['account_status']]);$id=(int)$pdo->lastInsertId();log_audit($pdo,'CREATE_ACCOUNT','account',$id,'Created '.$role.' account');redirect('accounts.php');}catch(PDOException $e){$error='Could not create account. The username may already exist.';}}}
